import java.util.*;class Solution{Map<Integer,List<String>>m=new HashMap<>();List<String>f(String s,int i,List<String>w){if(m.containsKey(i))return m.get(i);List<String>r=new ArrayList<>();if(i==s.length()){r.add("");return r;}for(String x:w)if(i+x.length()<=s.length()&&s.startsWith(x,i))for(String t:f(s,i+x.length(),w))r.add(x+(t.isEmpty()?"":" "+t));m.put(i,r);return r;}public List<String> wordBreak(String s,List<String>w){return f(s,0,w);}}
